def pipeline_report(rollout_seconds, train_seconds, batches):
    if rollout_seconds <= 0 or train_seconds <= 0:
        raise ValueError("stage times must be positive")
    if isinstance(batches, bool) or not isinstance(batches, int) or batches <= 0:
        raise ValueError("batches must be a positive integer")

    sequential = batches * (rollout_seconds + train_seconds)
    period = max(rollout_seconds, train_seconds)
    pipelined = rollout_seconds + train_seconds + (batches - 1) * period
    return {
        "sequential_total": sequential,
        "pipeline_total": pipelined,
        "period": period,
        "speedup": sequential / pipelined,
    }
```

