import numpy as np


def importance_weights(current_logprobs, behavior_logprobs, max_log_ratio=None):
    current = np.asarray(current_logprobs, dtype=float)
    behavior = np.asarray(behavior_logprobs, dtype=float)
    if current.ndim != 1 or current.shape != behavior.shape or current.size == 0:
        raise ValueError("inputs must be non-empty 1-D arrays of equal shape")
    if not np.isfinite(current).all() or not np.isfinite(behavior).all():
        raise ValueError("log probabilities must be finite")
    if np.any(current > 0) or np.any(behavior > 0):
        raise ValueError("log probabilities must be non-positive")

    log_ratio = current - behavior
    if max_log_ratio is not None:
        if not np.isfinite(max_log_ratio):
            raise ValueError("max_log_ratio must be finite")
        log_ratio = np.minimum(log_ratio, max_log_ratio)
    return np.exp(log_ratio)


def effective_sample_size(weights, normalized=False):
    w = np.asarray(weights, dtype=float)
    if w.ndim != 1 or w.size == 0 or not np.isfinite(w).all():
        raise ValueError("weights must be a finite non-empty vector")
    if np.any(w < 0):
        raise ValueError("weights must be non-negative")
    denom = float(np.dot(w, w))
    if denom == 0:
        raise ValueError("at least one weight must be positive")
    ess = float(w.sum() ** 2 / denom)
    return ess / w.size if normalized else ess
```

