from math import sqrt


def synchronization_schedule(sync_every, updates):
    if isinstance(sync_every, bool) or not isinstance(sync_every, int) or sync_every <= 0:
        raise ValueError("sync_every must be positive")
    if isinstance(updates, bool) or not isinstance(updates, int) or updates <= 0:
        raise ValueError("updates must be positive")
    return [step % sync_every for step in range(updates)]


def optimal_checkpoint_interval(checkpoint_seconds, mtbf_seconds):
    if checkpoint_seconds <= 0 or mtbf_seconds <= 0:
        raise ValueError("times must be positive")
    return sqrt(2 * checkpoint_seconds * mtbf_seconds)
```

```python
def diagnose_pipeline(metrics):
    required = {
        "trainer_idle_fraction",
        "rollout_idle_fraction",
        "verifier_fraction",
        "weight_sync_fraction",
        "queue_growth_per_minute",
        "normalized_ess",
        "oom_events",
    }
    missing = required - set(metrics)
    if missing:
        raise ValueError("missing metrics: " + ", ".join(sorted(missing)))

    bounded = required - {"queue_growth_per_minute", "oom_events"}
    for key in bounded:
        if not 0 <= metrics[key] <= 1:
            raise ValueError(f"{key} must lie in [0, 1]")
    if metrics["oom_events"] < 0:
        raise ValueError("oom_events must be non-negative")

    hypotheses = []
    if metrics["trainer_idle_fraction"] > 0.25 and metrics["queue_growth_per_minute"] <= 0:
        hypotheses.append("check rollout, verifier, and input supply")
    if metrics["verifier_fraction"] > 0.30:
        hypotheses.append("profile the verifier critical path")
    if metrics["weight_sync_fraction"] > 0.20:
        hypotheses.append("profile weight transfer and conversion")
    if metrics["normalized_ess"] < 0.50:
        hypotheses.append("separate policy lag from training-inference mismatch")
    if metrics["oom_events"] > 0:
        hypotheses.append("measure phase-specific peaks, KV cache, activations, and transfer buffers")
    if not hypotheses:
        hypotheses.append("inspect a stage-level trace")
    return hypotheses
```

The important design choice is that outputs are hypotheses that can be tested with a targeted measurement. A single aggregate metric rarely identifies a root cause.
